#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations/';

function logWithTimestamp(message) {
    const timestamp = new Date().toISOString();
    console.log(`[${timestamp}] ${message}`);
}

function ensureMigrationsDirectoryExists() {
    if (!fs.existsSync(MIGRATIONS_DIR)) {
        logWithTimestamp(`Creating migrations directory: ${MIGRATIONS_DIR}`);
        fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
        logWithTimestamp('Migrations directory created');
    }
}

function getMigrationFiles() {
    ensureMigrationsDirectoryExists();

    try {
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract timestamp/number from filename for proper ordering
                const numA = extractMigrationNumber(a);
                const numB = extractMigrationNumber(b);
                return numA - numB;
            });

        return sqlFiles;
    } catch (error) {
        logWithTimestamp(`Error reading migrations directory: ${error.message}`);
        return [];
    }
}

function extractMigrationNumber(filename) {
    // Common migration naming patterns:
    // 001_initial_setup.sql
    // 20240101000000_create_users_table.sql
    // 1_create_table.sql

    const match = filename.match(/^(\d+)[_-]/);
    if (match) {
        return parseInt(match[1], 10);
    }

    // If no number found, use the filename itself for alphabetical ordering
    return filename;
}

function logMigrationPlan(migrationFiles) {
    logWithTimestamp('Migration plan:');
    logWithTimestamp('='.repeat(50));

    if (migrationFiles.length === 0) {
        logWithTimestamp('No migration files found in the migrations directory');
        return;
    }

    migrationFiles.forEach((file, index) => {
        const migrationNumber = index + 1;
        logWithTimestamp(`${migrationNumber}. ${file}`);
    });

    logWithTimestamp('='.repeat(50));
    logWithTimestamp(`Total migrations to apply: ${migrationFiles.length}`);
}

function main() {
    logWithTimestamp('Starting migration script');
    logWithTimestamp(`Looking for migrations in: ${MIGRATIONS_DIR}`);

    const migrationFiles = getMigrationFiles();
    logMigrationPlan(migrationFiles);

    logWithTimestamp('Migration plan complete (dry run - no changes made)');
    logWithTimestamp('To actually apply migrations, you would:');
    logWithTimestamp('1. Read each SQL file content');
    logWithTimestamp('2. Execute the SQL against your database');
    logWithTimestamp('3. Track which migrations have been applied');
}

// Handle command line arguments
if (require.main === module) {
    main();
}

module.exports = {
    getMigrationFiles,
    logMigrationPlan,
    extractMigrationNumber
};

-- Initial database setup
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS migrations (
    id SERIAL PRIMARY KEY,
    filename VARCHAR(255) UNIQUE NOT NULL,
    applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create posts table
CREATE TABLE IF NOT EXISTS posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create indexes for better performance
CREATE INDEX IF NOT EXISTS idx_posts_user_id ON posts(user_id);
CREATE INDEX IF NOT EXISTS idx_posts_created_at ON posts(created_at);

