function readMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist`);
      return [];
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => {
        // Natural sort to handle numbered migrations (e.g., 001_initial.sql, 002_alter_table.sql)
        const aNum = extractMigrationNumber(a);
        const bNum = extractMigrationNumber(b);
        return aNum - bNum;
      });

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

function extractMigrationNumber(filename) {
  // Extract numeric prefix from filename (e.g., "001_initial.sql" -> 1)
  const match = filename.match(/^(\d+)/);
  return match ? parseInt(match[1], 10) : 0;
}

function logMigrations(migrations) {
  if (migrations.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):`);
  console.log('='.repeat(50));

  migrations.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('='.repeat(50));
  console.log('Migration files would be applied in the above order.');
}

// Main execution
function main() {
  console.log('Migration Script');
  console.log('='.repeat(50));

  const migrations = readMigrations();
  logMigrations(migrations);
}

// Run if this script is executed directly
