const fs = require('fs');
const path = require('path');

// Function to read migration files from the ./migrations/ directory
function readMigrationFiles() {
    const migrationsDir = './migrations/';

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.log('Migrations directory not found.');
            return [];
        }

        // Check if it's actually a directory
        const stats = fs.statSync(migrationsDir);
        if (!stats.isDirectory()) {
            console.log('Migrations path is not a directory.');
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for .sql files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        // Sort files alphabetically (assuming they have timestamp prefixes)
        const sortedFiles = sqlFiles.sort();

        return sortedFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

// Function to validate if a file looks like a migration file
function isValidMigrationFile(filename) {
    const migrationPattern = /^\d+_.+\.sql$/;
    return migrationPattern.test(filename);
}

// Function to read DATABASE_URL from .env.test file
function readDatabaseUrl() {
    const envFile = '.env.test';

    try {
        // Check if .env.test file exists
        if (!fs.existsSync(envFile)) {
            console.log(`\n${envFile} file not found.`);
            return null;
        }

        // Read the file content
        const content = fs.readFileSync(envFile, 'utf8');

        // Parse for DATABASE_URL
        const lines = content.split('\n');
        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip comments and empty lines
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Look for DATABASE_URL (case insensitive and with optional export)
            const urlMatch = trimmedLine.match(/^(?:export\s+)?DATABASE_URL\s*=\s*(.+)/i);
            if (urlMatch) {
                const url = urlMatch[1].trim();

                // Remove quotes if present
                const cleanUrl = url.replace(/^['"]|['"]$/g, '');

                return cleanUrl;
            }
        }

        console.log(`\nDATABASE_URL not found in ${envFile}.`);
        return null;

    } catch (error) {
        console.error(`\nError reading ${envFile}:`, error.message);
        return null;
    }
}

// Function to validate and log database connection info
function logDatabaseConnection() {
    const databaseUrl = readDatabaseUrl();

    if (databaseUrl) {
        console.log(`✅ Successfully read DATABASE_URL from .env.test`);

        // Extract database type for logging (optional)
        let dbType = 'database';
        if (databaseUrl.includes('postgres://') || databaseUrl.includes('postgresql://')) {
            dbType = 'PostgreSQL';
        } else if (databaseUrl.includes('mysql://')) {
            dbType = 'MySQL';
        } else if (databaseUrl.includes('sqlite://')) {
            dbType = 'SQLite';
        }

        console.log(`📊 Would connect to ${dbType} with the provided connection string`);
        console.log('🔒 Connection string masked for security');

        // Log a masked version of the URL for security
        const maskedUrl = databaseUrl.replace(/:[^:@]*@/, ':***@');
        console.log(`🔗 ${maskedUrl}`);

        return true;
    } else {
        console.log('❌ No database connection string available');
        return false;
    }
}

// Function to log migration files in order
function logMigrations() {
    console.log('Database Migration Script');
    console.log('=========================');

    // Log database connection information first
    console.log('\n🔌 Database Connection Setup:');
    const hasDbConnection = logDatabaseConnection();

    console.log('\n📁 Reading migration files from ./migrations/');
    console.log('');

    const migrationFiles = readMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No migration files found.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    // Log each file in order with validation
    migrationFiles.forEach((file, index) => {
        const isValid = isValidMigrationFile(file);
        const status = isValid ? '✅' : '⚠️';
        console.log(`${index + 1}. ${file} ${status}`);

