// Function to read all environment variables from .env.test file
function readAllEnvVariables() {
    const envFile = '.env.test';

    try {
        // Check if .env.test file exists
        if (!fs.existsSync(envFile)) {
            console.log(`\n${envFile} file not found.`);
            return {};
        }

        // Read the file content
        const content = fs.readFileSync(envFile, 'utf8');
        const envVars = {};

        // Parse all environment variables
        const lines = content.split('\n');
        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip comments and empty lines
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Match environment variable assignments
            const envMatch = trimmedLine.match(/^(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)/i);
            if (envMatch) {
                const key = envMatch[1].trim();
                let value = envMatch[2].trim();

                // Remove quotes if present
                value = value.replace(/^['"]|['"]$/g, '');

                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.error(`\nError reading ${envFile}:`, error.message);
        return {};
    }
}

