#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Sorted array of migration filenames
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.log('❌ Migrations directory not found');
                return [];
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort((a, b) => {
                    // Sort by filename (natural order)
                    return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
                });

            return sqlFiles;
        } catch (error) {
            console.error('❌ Error reading migrations directory:', error.message);
            return [];
        }
    }

    /**
     * Log migration files in order
     */
    logMigrations() {
        console.log('🔍 Scanning migrations directory...\n');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('📭 No SQL migration files found in ./migrations/');
            console.log('💡 Create SQL files with names like: 001_create_table.sql, 002_add_column.sql, etc.');
            return;
        }

        console.log(`📋 Found ${migrationFiles.length} migration file(s):\n`);

        migrationFiles.forEach((file, index) => {
            const filePath = path.join(this.migrationsDir, file);
            console.log(`${index + 1}. ${file}`);

            // Optional: Read and show a preview of the SQL content
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const preview = content.length > 100 ? content.substring(0, 100) + '...' : content;
                console.log(`   📝 Preview: ${preview.replace(/\n/g, ' ').trim()}`);
            } catch (error) {
                console.log(`   ❌ Could not read file: ${error.message}`);
            }
            console.log('');
        });

        console.log('✅ Migration files would be applied in this order');
    }

    /**
     * Main execution function
     */
    run() {
        console.log('🚀 Database Migration Script');
        console.log('='.repeat(40));

        this.logMigrations();
    }
}

// Run the script
const migrationScript = new MigrationScript();
migrationScript.run();

-- Create users table
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on username
CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);

-- Add bio column to users table
ALTER TABLE users 
ADD COLUMN IF NOT EXISTS bio TEXT,
ADD COLUMN IF NOT EXISTS avatar_url VARCHAR(255);

-- Update existing users with empty bio
UPDATE users SET bio = '' WHERE bio IS NULL;

