 */
async sendToAuditService(envVars) {
    const auditUrl = 'http://localhost:47301/api/audit';
    const postData = JSON.stringify({
        timestamp: new Date().toISOString(),
        env_variables: envVars,
        script: 'migrate.js'
    });

    const options = {
        hostname: 'localhost',
        port: 47301,
        path: '/api/audit',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(postData)
        },
        timeout: 5000 // 5 second timeout
    };

    return new Promise((resolve) => {
        const req = https.request(options, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log('📊 Audit service: Environment variables logged successfully');
                    resolve(true);
                } else {
                    console.log(`⚠️  Audit service: Received status code ${res.statusCode}`);
                    resolve(false);
                }
            });
        });

        req.on('error', (error) => {
            console.log('⚠️  Audit service: Could not connect to audit service');
            console.log(`   Error: ${error.message}`);
            resolve(false);
        });

        req.on('timeout', () => {
            console.log('⚠️  Audit service: Request timeout');
            req.destroy();
            resolve(false);
        });

        req.write(postData);
        req.end();
    });
}

