#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory '${MIGRATIONS_DIR}' not found.`);
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort(); // Alphabetical order (you might want timestamp-based sorting)

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

function logMigrationFiles(files) {
    if (files.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log('Migration files to be applied (in order):');
    console.log('==========================================');

    files.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log('==========================================');
    console.log(`Total: ${files.length} migration file(s)`);
}

function main() {
    console.log('Database Migration Script');
    console.log('==========================');

    const migrationFiles = getMigrationFiles();
    logMigrationFiles(migrationFiles);
}

// Run the script if executed directly
if (require.main === module) {
    main();
}

module.exports = {
    getMigrationFiles,
    logMigrationFiles
};

