#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const MIGRATIONS_DIR = './migrations';

// Function to read and sort migration files
function getMigrationFiles() {
    try {
        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them numerically/chronologically
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract numeric prefixes for sorting
                const aNum = parseInt(a.split('_')[0]) || 0;
                const bNum = parseInt(b.split('_')[0]) || 0;
                return aNum - bNum;
            });

        return sqlFiles;
    } catch (error) {
        if (error.code === 'ENOENT') {
            console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist`);
            process.exit(1);
        }
        throw error;
    }
}

// Main function to log migration files
function logMigrationFiles() {
    console.log('Reading migration files from:', MIGRATIONS_DIR);
    console.log('');

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No SQL migration files found in the migrations directory.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('------------------------------------------------');

    migrationFiles.forEach((file, index) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        const fileStats = fs.statSync(filePath);
        const fileSize = (fileStats.size / 1024).toFixed(2); // Size in KB

        console.log(`${index + 1}. ${file} (${fileSize} KB)`);
    });

    console.log('');
    console.log('Migration files would be applied in this order.');
}

// Execute the script
logMigrationFiles();

-- Create posts table
CREATE TABLE posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id),
    title VARCHAR(200) NOT NULL,
    content TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on user_id for faster queries
CREATE INDEX idx_posts_user_id ON posts(user_id);

-- Add roles column to users table
ALTER TABLE users ADD COLUMN role VARCHAR(20) DEFAULT 'user';

-- Create index on role for faster queries
CREATE INDEX idx_users_role ON users(role);

-- Create comments table
CREATE TABLE comments (
    id SERIAL PRIMARY KEY,
    post_id INTEGER REFERENCES posts(id),
    user_id INTEGER REFERENCES users(id),
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create indexes
CREATE INDEX idx_comments_post_id ON comments(post_id);
CREATE INDEX idx_comments_user_id ON comments(user_id);

