const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */
function migrate() {
    const migrationsDir = './migrations/';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log('Migrations directory not found:', migrationsDir);
        console.log('Creating empty migrations directory...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        return;
    }

    // Read all files from migrations directory
    let files;
    try {
        files = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return;
    }

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
            // Sort by natural order (numeric prefixes if present)
            return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
        });

    console.log(`Found ${sqlFiles.length} SQL migration files:`);

    if (sqlFiles.length === 0) {
        console.log('No migration files found in', migrationsDir);
        console.log('Add SQL files with .sql extension to run migrations');
        return;
    }

    // Log each migration file in order
    sqlFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        console.log(`${index + 1}. ${file}`);

        // Optional: Read and display first few lines for preview
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const preview = content.split('\n').slice(0, 3).join('\n');
            if (preview.trim()) {
                console.log(`   Preview: ${preview.substring(0, 100)}${preview.length > 100 ? '...' : ''}`);
            }
        } catch (error) {
            console.log(`   Error reading file: ${error.message}`);
        }
    });

    console.log('\nMigration files would be applied in the order shown above.');
    console.log('To actually execute these migrations, you would:');
    console.log('1. Connect to your database');
    console.log('2. Read each SQL file');
    console.log('3. Execute the SQL statements');
    console.log('4. Track which migrations have been applied');
}

// Run the migration script
migrate();

