/**
 * Mask database URL for secure logging (hides password)
 */
function maskDatabaseUrl(url) {
    try {
        // Parse the URL to extract components
        const urlPattern = /^(postgresql|postgres):\/\/([^:]+):([^@]+)@([^\/]+)\/(.+)$/;
        const match = url.match(urlPattern);

        if (match) {
            const [_, protocol, username, password, host, database] = match;
            return `${protocol}://${username}:******@${host}/${database}`;
        }

        // If it doesn't match the expected pattern, return as-is but mask any obvious passwords
        return url.replace(/:[^@]+@/, ':******@');
    } catch (error) {
        // If parsing fails, return a masked version
        return url.replace(/:[^@]+@/, ':******@');
    }
}

