#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Function to read and process migration files
function processMigrations() {
    const migrationsDir = './migrations/';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log(`Directory ${migrationsDir} does not exist.`);
        return;
    }

    try {
        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Sort by filename (natural sort for migration numbering)
                return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
            });

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found in the migrations directory.');
            return;
        }

        console.log(`Found ${sqlFiles.length} migration file(s):`);
        console.log('='.repeat(50));

        // Log each migration file that would be applied
        sqlFiles.forEach((file, index) => {
            const filePath = path.join(migrationsDir, file);
            const fileStats = fs.statSync(filePath);

            console.log(`${index + 1}. ${file}`);
            console.log(`   Path: ${filePath}`);
            console.log(`   Size: ${fileStats.size} bytes`);
            console.log(`   Modified: ${fileStats.mtime.toLocaleString()}`);
            console.log('');
        });

        console.log('✓ Would apply the above migration files in this order.');

    } catch (error) {
        console.error('Error processing migration files:', error.message);
    }
}

// Run the migration processor
processMigrations();

-- Create categories table
CREATE TABLE categories (
    id SERIAL PRIMARY KEY,
    name VARCHAR(50) UNIQUE NOT NULL,
    description TEXT
);

-- Add category_id to posts table
ALTER TABLE posts ADD COLUMN category_id INTEGER REFERENCES categories(id);

