#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationLogger {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.ensureMigrationsDir();
  }

  ensureMigrationsDir() {
    if (!fs.existsSync(this.migrationsDir)) {
      console.log('Creating migrations directory...');
      fs.mkdirSync(this.migrationsDir, { recursive: true });
    }
  }

  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for .sql files and sort them numerically/alphabetically
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
          // Extract numbers from filenames for proper sorting (e.g., 001, 002, etc.)
          const numA = parseInt(a.split('_')[0]) || 0;
          const numB = parseInt(b.split('_')[0]) || 0;
          return numA - numB;
        });

      return sqlFiles;
    } catch (error) {
      console.error('Error reading migrations directory:', error.message);
      return [];
    }
  }

  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migrations from: ${this.migrationsDir}`);
    console.log('');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found in the migrations directory.');
      console.log('Please add SQL files to the ./migrations/ folder.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);

      // Optional: Log the first few lines of each SQL file
      try {
        const filePath = path.join(this.migrationsDir, file);
        const content = fs.readFileSync(filePath, 'utf8');
        const firstLine = content.split('\n')[0].trim();

        if (firstLine) {
          console.log(`   → ${firstLine}${firstLine.length > 50 ? '...' : ''}`);
        }
      } catch (error) {
        console.log(`   → [Could not read file content]`);
      }

      console.log('');
    });

    console.log('=== Migration logging complete ===');
  }
}

// Run if this script is executed directly
if (require.main === module) {
  const migrationLogger = new MigrationLogger();
  migrationLogger.logMigrations();
}

module.exports = MigrationLogger;

