#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Function to get all SQL files from migrations directory
function getMigrationFiles() {
    const migrationsDir = './migrations/';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log('Migrations directory does not exist. Creating it...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log('No migration files found.');
        return [];
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
            // Sort numerically if files start with numbers (e.g., 001_create_table.sql)
            const numA = parseInt(a.split('_')[0]) || 0;
            const numB = parseInt(b.split('_')[0]) || 0;
            return numA - numB;
        });

    return sqlFiles;
}

// Main function
function runMigration() {
    console.log('🔍 Scanning migrations directory...');

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('📭 No SQL migration files found in ./migrations/');
        console.log('💡 Create SQL files in the format: 001_descriptive_name.sql');
        return;
    }

    console.log(`📋 Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log('');
    console.log('✅ Migration plan complete. These files would be applied in order.');
    console.log('💡 To actually apply migrations, you would need database connection logic.');
}

