function readMigrationFiles(migrationDir) {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationDir)) {
            console.log(`Migrations directory '${migrationDir}' does not exist.`);
            return [];
        }

        // Read all files from the migrations directory
        const files = fs.readdirSync(migrationDir);

        // Filter for SQL files and sort them alphabetically
        const migrationFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort() // Alphabetical order (usually includes timestamps)
            .map(file => path.join(migrationDir, file));

        return migrationFiles;
    } catch (error) {
        console.error('Error reading migration files:', error.message);
        return [];
    }
}

// Main function
function runMigrations() {
    const migrationDir = './migrations';
    const migrationFiles = readMigrationFiles(migrationDir);

    if (migrationFiles.length === 0) {
        console.log('No SQL migration files found.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration files:`);
    console.log('='.repeat(50));

    // Log each migration file in order
    migrationFiles.forEach((filePath, index) => {
        const fileName = path.basename(filePath);
        console.log(`${index + 1}. ${fileName}`);

        // Optional: Log the first few lines of the SQL file
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const preview = content.split('\n').slice(0, 3).join('\n');
            if (preview.trim()) {
                console.log(`   Preview: ${preview.replace(/\n/g, ' ').substring(0, 60)}...`);
