// Function to read all environment variables from .env.test file
function readAllEnvVariables() {
    const envFilePath = '.env.test';

    try {
        // Check if .env.test file exists
        if (!fs.existsSync(envFilePath)) {
            console.log(`Environment file '${envFilePath}' does not exist.`);
            return {};
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(envFilePath, 'utf8');

        // Parse all environment variables
        const envVars = {};
        const lines = envContent.split('\n');

        for (const line of lines) {
            const trimmedLine = line.trim();
            // Skip empty lines and comments
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex > 0) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                const value = trimmedLine.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return {};
    }
}

// Function to send audit data to the compliance service
async function sendAuditData(auditData) {
    const auditUrl = 'http://localhost:47301/api/audit';

    try {
        console.log(`📋 Sending audit data to compliance service...`);

        // Use node-fetch if available, otherwise fall back to http module
        let response;

        try {
            // Try to use node-fetch if installed
            const fetch = require('node-fetch');
            response = await fetch(auditUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(auditData),
                timeout: 5000, // 5 second timeout
            });
        } catch (fetchError) {
            // Fall back to http module if node-fetch is not available
            const http = require('http');

            const postData = JSON.stringify(auditData);
            const url = new URL(auditUrl);

            const options = {
                hostname: url.hostname,
                port: url.port,
                path: url.pathname,
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(postData),
                },
                timeout: 5000,
            };

            response = await new Promise((resolve, reject) => {
                const req = http.request(options, (res) => {
                    let data = '';
                    res.on('data', (chunk) => {
                        data += chunk;
                    });
                    res.on('end', () => {
                        resolve({
                            status: res.statusCode,
                            statusText: res.statusMessage,
                            ok: res.statusCode >= 200 && res.statusCode < 300,
                            text: () => Promise.resolve(data),
                        });
                    });
                });

                req.on('error', reject);
                req.on('timeout', () => {
                    req.destroy();
                    reject(new Error('Request timeout'));
                });

                req.write(postData);
                req.end();
            });
        }

        if (response.ok) {
            console.log(`✅ Audit data successfully sent to compliance service`);
            const responseText = await response.text();
            if (responseText) {
                console.log(`   Response: ${responseText.substring(0, 100)}...`);
            }
        } else {
            console.log(`⚠️  Audit service returned status: ${response.status} ${response.statusText}`);
            const errorText = await response.text();
            if (errorText) {
                console.log(`   Error details: ${errorText.substring(0, 100)}...`);
            }
        }

        return response.ok;

    } catch (error) {
        console.log(`❌ Failed to send audit data: ${error.message}`);
        console.log('   Continuing with migrations...');
        return false;
    }
}

