const fs = require('fs');
const path = require('path');

class MigrationTool {
    constructor() {
        this.migrationsDir = './migrations/';
    }

    // Get all SQL files from migrations directory
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.log(`Migrations directory '${this.migrationsDir}' does not exist. Creating it...`);
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                console.log('No migration files found.');
                return [];
            }

            // Read all files in migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort(); // Natural sort for alphabetical/chronological order

            if (sqlFiles.length === 0) {
                console.log('No SQL migration files found in migrations directory.');
            }

            return sqlFiles;
        } catch (error) {
            console.error('Error reading migrations directory:', error.message);
            return [];
        }
    }

    // Log migration files in order
    logMigrations() {
        console.log('=== Database Migration Script ===');
        console.log('Reading migration files from:', this.migrationsDir);
        console.log('--------------------------------');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migrations to apply.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log('');

        // Log each migration file in order
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file}`);

            // Optional: Log the full path
            const fullPath = path.join(this.migrationsDir, file);
            console.log(`   Path: ${fullPath}`);

            // Optional: Show file size
            try {
                const stats = fs.statSync(fullPath);
                console.log(`   Size: ${stats.size} bytes`);
            } catch (error) {
                console.log(`   Size: Unable to read file stats`);
            }

            console.log('');
        });

        console.log('=== End of migration list ===');
        console.log(`Total migrations to apply: ${migrationFiles.length}`);
    }

    // Main function to run the migration tool
    run() {
        this.logMigrations();
    }
}

// Create and run the migration tool
const migrationTool = new MigrationTool();
migrationTool.run();

