const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations/';

// Function to read and sort migration files
function getMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory ${MIGRATIONS_DIR} not found. Creating empty directory...`);
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('No migration files to process.');
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract numbers from filenames for proper ordering
                const numA = parseInt(a.match(/^\d+/)?.[0] || '0');
                const numB = parseInt(b.match(/^\d+/)?.[0] || '0');
                return numA - numB;
            });

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

// Main function
function runMigrations() {
    console.log('=== Database Migration Script ===\n');

    const migrationFiles = getMigrations();

    if (migrationFiles.length === 0) {
        console.log('No migration files found in', MIGRATIONS_DIR);
        console.log('\nExpected format: 001_initial_setup.sql, 002_add_users_table.sql, etc.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        const fileInfo = fs.statSync(filePath);
        const sizeKB = (fileInfo.size / 1024).toFixed(2);

        console.log(`${index + 1}. ${file} (${sizeKB} KB)`);

        // Optional: Read and log first few lines of SQL content
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLines = content.split('\n').slice(0, 3).filter(line => line.trim());
            if (firstLines.length > 0) {
                console.log('   Preview:', firstLines[0].substring(0, 60) + (firstLines[0].length > 60 ? '...' : ''));
            }
        } catch (readError) {
            console.log('   [Could not read file content]');
        }

        console.log(''); // Empty line for readability
    });

    console.log('Migration files would be applied in the order shown above.');
    console.log('\nTo actually execute these migrations, you would:');
    console.log('1. Connect to your database');
    console.log('2. Execute each SQL file in order');
    console.log('3. Track which migrations have been applied');
}

// Run the script
runMigrations();

