#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

class MigrationScript {
    constructor() {
        this.migrationsDir = './migrations/';
        this.init();
    }

    init() {
        this.validateMigrationsDirectory();
        this.listAndOrderMigrations();
    }

    validateMigrationsDirectory() {
        try {
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`❌ Error: Migrations directory '${this.migrationsDir}' does not exist`);
                process.exit(1);
            }

            const stats = fs.statSync(this.migrationsDir);
            if (!stats.isDirectory()) {
                console.error(`❌ Error: '${this.migrationsDir}' is not a directory`);
                process.exit(1);
            }

            console.log(`✓ Found migrations directory: ${this.migrationsDir}`);
        } catch (error) {
            console.error(`❌ Error accessing migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    listAndOrderMigrations() {
        try {
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files only
            const sqlFiles = files.filter(file => 
                file.toLowerCase().endsWith('.sql')
            );

            if (sqlFiles.length === 0) {
                console.log('ℹ️  No SQL migration files found in the migrations directory');
                return;
            }

            // Sort files alphabetically (which typically reflects chronological order)
            const orderedMigrations = sqlFiles.sort();

            console.log('\n📋 Migration files found (ordered by filename):');
            console.log('='.repeat(50));

            orderedMigrations.forEach((file, index) => {
                const filePath = path.join(this.migrationsDir, file);
                let fileInfo = '';

                try {
                    const stats = fs.statSync(filePath);
                    const fileSize = this.formatFileSize(stats.size);
                    const modified = stats.mtime.toLocaleString();
                    fileInfo = ` | ${fileSize} | ${modified}`;
                } catch (error) {
                    fileInfo = ' | (Unable to read file info)';
                }

                console.log(`${(index + 1).toString().padStart(2, '0')}. ${file}${fileInfo}`);
            });

            console.log('='.repeat(50));
            console.log(`Total: ${orderedMigrations.length} migration file(s) would be applied`);

        } catch (error) {
            console.error(`❌ Error reading migration files: ${error.message}`);
            process.exit(1);
        }
    }

    formatFileSize(bytes) {
        if (bytes === 0) return '0 B';
        const k = 1024;
        const sizes = ['B', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }
}

// Handle command line arguments
const args = process.argv.slice(2);

// Add help functionality
if (args.includes('--help') || args.includes('-h')) {
    console.log(`
Usage: node migrate.js [options]

Options:
  --help, -h     Show this help message
  --verbose, -v  Show verbose output (currently the default)

This script reads SQL files from the './migrations/' directory
and displays them in alphabetical order (typically chronological).

Example migration naming convention:
  001_create_users_table.sql
  002_add_email_column.sql
  003_create_posts_table.sql
`);
    process.exit(0);
}

// Run the migration script
new MigrationScript();

-- Create users table
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create index on username for faster lookups
CREATE INDEX idx_users_username ON users(username);

-- Add email verification columns to users table
ALTER TABLE users 
ADD COLUMN email_verified BOOLEAN DEFAULT FALSE,
ADD COLUMN verification_token VARCHAR(100),
ADD COLUMN verified_at TIMESTAMP;

-- Add index for faster verification lookups
CREATE INDEX idx_users_verification_token ON users(verification_token);

COMMENT ON COLUMN users.email_verified IS 'Whether the user''s email has been verified';
COMMENT ON COLUMN users.verification_token IS 'Token used for email verification';
COMMENT ON COLUMN users.verified_at IS 'Timestamp when email was verified';

-- Create posts table for user content
CREATE TABLE posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    content TEXT NOT NULL,
    status VARCHAR(20) DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    published_at TIMESTAMP
);

-- Create indexes for better performance
CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_status ON posts(status);
CREATE INDEX idx_posts_published_at ON posts(published_at);

-- Add foreign key constraint
ALTER TABLE posts 
ADD CONSTRAINT fk_posts_user_id 
FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;

