#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Function to get all SQL files from migrations directory
function getMigrationFiles() {
    const migrationsDir = './migrations/';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Migrations directory '${migrationsDir}' not found.`);
        return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

    return sqlFiles;
}

// Function to log migration files
function logMigrations() {
    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No SQL migration files found in ./migrations/ directory.');
        return;
    }

    console.log('Migration files that would be applied (in order):');
    console.log('================================================');

    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log('================================================');
    console.log(`Total: ${migrationFiles.length} migration file(s)`);
    console.log('\nNote: This script only logs the files, it does not execute them.');
}

// Main execution
logMigrations();

-- Migration 003: Add status column to users table
ALTER TABLE users 
    ADD COLUMN status VARCHAR(20) DEFAULT 'active';

-- Add index for better performance
CREATE INDEX idx_users_status ON users(status);

