            });
        });

        req.on('error', (error) => {
            console.warn(`⚠️  Audit service connection failed: ${error.message}`);
            console.warn('   Continuing with migration (audit is non-critical)...');
            resolve(false); // Don't fail the migration for audit issues
        });

        req.write(data);
        req.end();
    });
}

