const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */
function migrate() {
    const migrationsDir = './migrations';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.log(`Migrations directory '${migrationsDir}' not found.`);
        console.log('Creating migrations directory...');
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log('No migration files to apply.');
        return;
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
            // Extract numeric prefixes for proper ordering
            const numA = parseInt(a.split('_')[0]) || 0;
            const numB = parseInt(b.split('_')[0]) || 0;
            return numA - numB;
        });

    console.log(`Found ${sqlFiles.length} migration file(s):`);

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in ./migrations/ directory.');
        return;
    }

    // Log each migration file in order
    sqlFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        const fileContent = fs.readFileSync(filePath, 'utf8');

        console.log(`\n[${index + 1}/${sqlFiles.length}] ${file}:`);
        console.log('--- SQL Content Preview ---');

        // Show preview of the SQL content (first 200 chars)
        const preview = fileContent.trim().substring(0, 200);
        if (fileContent.length > 200) {
            console.log(`${preview}...`);
        } else {
            console.log(preview);
        }
        console.log('---------------------------');
    });

    console.log(`\nMigration script would apply ${sqlFiles.length} SQL file(s) in the order shown above.`);
}

// Run the migration if this file is executed directly
if (require.main === module) {
    migrate();
}

module.exports = { migrate };

-- Create posts table
CREATE TABLE posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create foreign key index for better performance
CREATE INDEX idx_posts_user_id ON posts(user_id);

-- Create index for searching posts by title
CREATE INDEX idx_posts_title ON posts(title);

-- Add profile fields to users table
ALTER TABLE users 
ADD COLUMN first_name VARCHAR(50),
ADD COLUMN last_name VARCHAR(50),
ADD COLUMN bio TEXT,
ADD COLUMN avatar_url VARCHAR(255);

-- Update the updated_at trigger function
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

-- Create trigger for users table
CREATE TRIGGER update_users_updated_at 
    BEFORE UPDATE ON users 
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

