#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations/';

function readMigrationsDirectory() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.log(`❌ Migrations directory '${MIGRATIONS_DIR}' does not exist`);
            console.log('👉 Creating empty migrations directory...');
            fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
            console.log('✅ Migrations directory created');
            return [];
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = files.filter(file => 
            file.endsWith('.sql') && 
            fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
        );

        if (sqlFiles.length === 0) {
            console.log('ℹ️  No SQL migration files found in the migrations directory');
            return [];
        }

        // Sort files by name (assuming naming convention like 001_initial.sql, 002_add_users.sql)
        const sortedFiles = sqlFiles.sort();

        return sortedFiles;
    } catch (error) {
        console.error('❌ Error reading migrations directory:', error.message);
        return [];
    }
}

function logMigrationFiles(files) {
    if (files.length === 0) {
        console.log('No migration files to apply');
        return;
    }

    console.log('\n📋 Migration files to apply (in order):\n');

    files.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);

        // Optional: Read and show the first few lines of the SQL file
        try {
            const filePath = path.join(MIGRATIONS_DIR, file);
            const content = fs.readFileSync(filePath, 'utf8');
            const firstLine = content.split('\n')[0].trim();

            if (firstLine && firstLine.length > 0) {
                console.log(`   💡 ${firstLine.length > 60 ? firstLine.substring(0, 60) + '...' : firstLine}`);
            }
        } catch (readError) {
            console.log(`   ⚠️  Could not read file contents`);
        }

        console.log(''); // Empty line for readability
    });

    console.log(`Total: ${files.length} migration file(s) ready to be applied`);
}

function main() {
    console.log('🚀 Database Migration Script\n');
    console.log(`📁 Reading migration files from: ${MIGRATIONS_DIR}\n`);

    const migrationFiles = readMigrationsDirectory();
    logMigrationFiles(migrationFiles);
}

// Run the script
main();

