function readEnvironmentFile() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_FILE)) {
            console.log(`❌ Environment file '${ENV_FILE}' does not exist`);
            return null;
        }

        // Read the environment file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');

        // Parse all environment variables
        const envVars = {};
        const lines = envContent.split('\n');

        for (const line of lines) {
            const trimmedLine = line.trim();
            // Skip empty lines and comments
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex > 0) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                const value = trimmedLine.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        }

        return envVars;

    } catch (error) {
        console.error('❌ Error reading environment file:', error.message);
        return null;
    }
}

function readDatabaseUrl(envVars) {
    if (!envVars || !envVars.DATABASE_URL) {
        console.log('❌ DATABASE_URL not found in environment file');
        return null;
    }
    return envVars.DATABASE_URL;
}

